--
-- Table structure for table `commission_runs`
--

DROP TABLE IF EXISTS `commission_runs`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `commission_runs` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `brand_id` bigint(20) NOT NULL,
  `advisor_id` bigint(20) NOT NULL,
  `cut_year` smallint(6) NOT NULL,
  `cut_month` tinyint(3) unsigned NOT NULL,
  `fortnight` enum('FIRST','SECOND') NOT NULL,
  `scheme_id` bigint(20) DEFAULT NULL,
  `units_total` int(10) unsigned NOT NULL DEFAULT 0,
  `total_commission` decimal(14,2) NOT NULL DEFAULT 0.00,
  `base_commission` decimal(14,2) NOT NULL DEFAULT 0.00 COMMENT 'Comisión pura calculada por rangos, sin ajuste manual',
  `manual_adjustment` decimal(14,2) DEFAULT NULL COMMENT 'Monto del ajuste manual aplicado por BRAND_OP',
  `manual_adjustment_type` enum('ADD','SUBTRACT') DEFAULT NULL,
  `manual_adjustment_note` varchar(500) DEFAULT NULL COMMENT 'Concepto obligatorio del ajuste (ej: Cobro de transporte)',
  `manual_adjustment_by` bigint(20) DEFAULT NULL COMMENT 'ID del usuario que aplicó el ajuste',
  `manual_adjustment_at` datetime DEFAULT NULL COMMENT 'Timestamp de cuando se aplicó el ajuste',
  `status` enum('DRAFT','CALCULATED','ADVISOR_APPROVED','ADVISOR_REJECTED','ASST_VALIDATED','SENT_TO_HR') NOT NULL DEFAULT 'DRAFT',
  `notes` varchar(255) DEFAULT NULL,
  `rejection_note` varchar(500) DEFAULT NULL,
  `created_by` bigint(20) DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `updated_at` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `idx_run_brand` (`brand_id`),
  KEY `idx_run_advisor` (`advisor_id`),
  KEY `idx_run_cut` (`cut_year`,`cut_month`,`fortnight`),
  KEY `idx_run_scheme` (`scheme_id`)
) ENGINE=InnoDB AUTO_INCREMENT=142 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

